struct Constant { const char* owner; const char* name; SEXP (*make)(); };
static const Constant rosetta_constants[] = {
    {nullptr, nullptr, nullptr}};
// Records the environment holding the R classes; returns the constants to define there.
SEXP rosetta_r_init(SEXP env) {
    return rosetta_r::boundary([&]() -> SEXP {
        if (TYPEOF(env) != ENVSXP) rosetta_r::fail("expected an environment");
        if (rosetta_r::module_env()) R_ReleaseObject(rosetta_r::module_env());
        R_PreserveObject(env);
        rosetta_r::module_env() = env;
        R_xlen_t count = 0;
        for (const auto* c = rosetta_constants; c->name; ++c) ++count;
        rosetta_r::Protect result(Rf_allocVector(VECSXP, count));
        rosetta_r::Protect owners(Rf_allocVector(STRSXP, count));
        rosetta_r::Protect labels(Rf_allocVector(STRSXP, count));
        for (R_xlen_t i = 0; i < count; ++i) {
            SET_VECTOR_ELT(result.get(), i, rosetta_constants[i].make());
            SET_STRING_ELT(owners.get(), i, Rf_mkChar(rosetta_constants[i].owner));
            SET_STRING_ELT(labels.get(), i, Rf_mkChar(rosetta_constants[i].name));
        }
        Rf_setAttrib(result.get(), R_NamesSymbol, labels.get());
        Rf_setAttrib(result.get(), Rf_install("owners"), owners.get());
        return result.get();
    });
}
SEXP rosetta_r_release(SEXP self) { return rosetta_r::boundary([&]() -> SEXP { return rosetta_r::release_object(self); }); }
SEXP rosetta_r_invoke(SEXP callable, SEXP args) { return rosetta_r::boundary([&]() -> SEXP { return rosetta_r::invoke_callable(callable, args); }); }
